actions.script:
allowed = true
if (!ec.user.isInGroup('ADMIN')) {
    def activeOrg = ec.user.getPreference('ACTIVE_ORGANIZATION')
    def parts = ec.entity.find('mantle.order.OrderPart').condition('orderId', orderId).disableAuthz().list()
    def owner = parts ? parts[0].customerPartyId : null
    if (owner == null || !activeOrg || activeOrg == '_NA_' || owner != activeOrg) {
        allowed = false
    }
}

def active=ec.user.getPreference('ACTIVE_ORGANIZATION')
def vendor=ec.entity.find('mantle.party.Party').condition('partyId',vendorPartyId).disableAuthz().one()
if(!active || active=='_NA_' || organizationPartyId!=active || !vendor || vendor.ownerPartyId!=active) {
    ec.message.addError('Choose a vendor from your active buying organization.');return
}
ec.service.sync().name('zenith.tax.TaxAccessServices.assert#Organization').parameters([organizationPartyId:active]).call()
if(ec.message.hasError()) return
if(!ec.entity.find('mantle.party.PartyRole').condition('partyId',vendorPartyId).condition('roleTypeId','Supplier').count()) {
    ec.message.addError('Choose a registered supplier for this bill.');return
}
def settings=ec.entity.find('zenith.erp.base.CompanySettings').condition('organizationPartyId',active).condition('settingKey','CURRENCY_UOM_ID').one()
currencyUomId=currencyUomId ?: settings?.settingValue
def currency=currencyUomId ? ec.entity.find('moqui.basic.Uom').condition('uomId',currencyUomId).one() : null
if(currency?.uomTypeEnumId!='UT_CURRENCY_MEASURE') {ec.message.addError('Choose a valid configured bill currency.');return}
if(![isImportPurchase,isReverseCharge,isCompositionDealer,itcEligible].every { it in ['Y','N'] } || (isReverseCharge=='Y' && isCompositionDealer=='Y')) {
    ec.message.addError('Choose valid import, supply and ITC settings.');return
}
if(isCompositionDealer=='Y') itcEligible='N'
if(purchaseOrderNumber) {
    def order=ec.entity.find('mantle.order.OrderHeader').condition('orderId',purchaseOrderNumber).disableAuthz().one()
    def parts=ec.entity.find('mantle.order.OrderPart').condition('orderId',purchaseOrderNumber).disableAuthz().list()
    if(!order || order.documentType!='PURCHASE_ORDER' || !(order.statusId in ['OrderApproved','OrderCompleted']) || !parts ||
        parts.any { it.customerPartyId!=active } || !parts.any { it.vendorPartyId==vendorPartyId } || order.currencyUomId!=currencyUomId) {
        ec.message.addError('Choose an approved purchase order for this organization, vendor and currency.');return
    }
}

if(quantity<=0 || unitAmount<0 || discountPercent<0 || discountPercent>100) {ec.message.addError('Use a positive quantity, nonnegative price and discount from 0 to 100.');return}
def product=productId ? ec.entity.find('mantle.product.Product').condition('productId',productId).disableAuthz().one() : null
if(productId && (!product || product.ownerPartyId!=invoice.toPartyId)) ec.message.addError('Choose a product from the buying organization.')
